def main():
    before = io.open(P, encoding="utf-8", newline="").read()
    if TAIL_ANCHOR not in before[-3000:]:
        print("[x] \u6587\u4ef6\u672b\u5c3e\u4e0d\u662f\u9884\u671f\u7684 \u00a76.393\uff0c\u505c\u624b\uff08\u522b\u628a\u4e24\u8f6e\u7684\u5185\u5bb9\u63a5\u9519\u5730\u65b9\uff09")
        print("    \u5b9e\u9645\u672b\u5c3e\uff1a" + before[-200:].replace("\n", "\\n"))
        return 1
    io.open(P, "a", encoding="utf-8", newline="").write(SEC)
    after = io.open(P, encoding="utf-8", newline="").read()
    print("  \u5b57\u8282\u6570 %d \u2192 %d(\u65b0\u589e %d)  \u6587\u4ef6\u672b\u884c=[%s]"
          % (len(before.encode("utf-8")), len(after.encode("utf-8")),
             len(after.encode("utf-8")) - len(before.encode("utf-8")),
             after.rstrip("\n").split("\n")[-1][:80]))
    assert after.startswith(before), "\u7eaf append \u5931\u8d25\uff08\u524d\u7f00\u4e0d\u540c\uff09\u21d2 \u5df2\u7ecf\u6539\u4e86\u65e7\u5185\u5bb9\uff01"
    print("PASS \u00a76.394 \u5df2\u8ffd\u52a0\uff0c\u4e14\u65e2\u6709\u5185\u5bb9\u9010\u5b57\u8282\u672a\u52a8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
